import string
for _ in range(int(input())):
	n = int(input())
	st = input()
	s = set()
	mp = {}
	letters = list(string.ascii_lowercase)

	def check(l, c):
		while l in mp:
			l = mp[l]
			if l == c:
				return True
		return False
	for c in st:
		if c in mp:
			continue
		for l in letters:
			if l == c or (l in mp and check(l, c) and (len(mp) < 25)):
				continue
			mp[c] = l
			letters.remove(l)
			break
	print(''.join((mp[c] for c in st)))
